package com.bank.portal.service;
import com.bank.portal.domain.*; import com.bank.portal.repository.*; import com.bank.portal.web.ApiDtos.*; import java.time.*; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class OnboardingService { private final CustomerOnboardingRequestRepository requests; private final CustomerRepository customers;
 @Transactional public OnboardingRequestView submit(OnboardingRequestInput r){String email=r.email().trim().toLowerCase(),pan=r.panNumber().trim().toUpperCase();if(customers.findByEmailIgnoreCase(email).isPresent())throw new IllegalStateException("An approved customer already uses this email.");if(requests.existsByEmailIgnoreCase(email)||requests.existsByPanNumber(pan))throw new IllegalStateException("A request already exists for this email or PAN.");CustomerOnboardingRequest q=new CustomerOnboardingRequest();q.setName(r.name().trim());q.setEmail(email);q.setMobileNumber(r.mobileNumber());q.setPanNumber(pan);q.setStatus(OnboardingRequestStatus.PENDING);return view(requests.save(q));}
 public List<OnboardingRequestView> pending(){return requests.findByStatusOrderByCreatedAtAsc(OnboardingRequestStatus.PENDING).stream().map(this::view).toList();}
 @Transactional public OnboardingRequestView review(Long id,OnboardingReviewInput r,String staff){CustomerOnboardingRequest q=requests.findById(id).orElseThrow(()->new IllegalArgumentException("Request not found"));if(q.getStatus()!=OnboardingRequestStatus.PENDING)throw new IllegalStateException("Request already reviewed");q.setStatus(r.status());q.setReviewComment(r.comment());q.setReviewedBy(staff);q.setReviewedAt(LocalDateTime.now());if(r.status()==OnboardingRequestStatus.APPROVED){Customer c=new Customer();c.setName(q.getName());c.setEmail(q.getEmail());c.setMobileNumber(q.getMobileNumber());c.setPanNumber(q.getPanNumber());customers.save(c);}return view(q);}
 private OnboardingRequestView view(CustomerOnboardingRequest q){return new OnboardingRequestView(q.getId(),q.getName(),q.getEmail(),q.getMobileNumber(),q.getPanNumber(),q.getStatus().name(),q.getReviewComment());}}
